/** Package only the exact, bounded native evidence generated by the disposable
 * macOS CI case. This is not an installer or a source-activation mechanism.
 * GitHub upload-artifact does not reliably collect files from /private/tmp.
 */
import fs from "node:fs/promises";
import path from "node:path";
import os from "node:os";
import {createHash} from "node:crypto";
import {fileURLToPath} from "node:url";
const fail=code=>Object.assign(Error(code),{code});
const sha=bytes=>createHash("sha256").update(bytes).digest("hex");
const exactStage=stage=>typeof stage==="string"&&/^\/private\/tmp\/gsa-directory-native-[A-Za-z0-9]{6}$/.test(stage);
const validRel=rel=>typeof rel==="string"&&rel.length<300&&rel.split("/").every(s=>s&&s!=="."&&s!==".."&&!s.includes("\\")&&!s.includes("\0"));
export async function packageNativeTreeEvidence(summaryFile,destination){
 const lines=(await fs.readFile(summaryFile,"utf8")).split("\n").filter(Boolean);
 const line=lines.findLast(v=>v.startsWith('{"state":'));
 if(!line)throw fail("TREE_SUMMARY_MISSING");
 const summary=JSON.parse(line);
 if(!exactStage(summary.stage)||!["TREE_NATIVE_CAPTURE_SUITE_OBSERVED","INCONCLUSIVE","BLOCKING"].includes(summary.state))throw fail("TREE_SUMMARY_UNSAFE");
 const stage=summary.stage;
 if(await fs.realpath(stage)!==stage)throw fail("TREE_STAGE_CHANGED");
 const root=await fs.lstat(stage);
 if(!root.isDirectory()||root.isSymbolicLink()||root.uid!==process.getuid()||(root.mode&0o777)!==0o700)throw fail("TREE_STAGE_UNSAFE");
 const report=JSON.parse(await fs.readFile(path.join(stage,"result.json"),"utf8"));
 if(report.stage!==stage||report.state!==summary.state||report.activation!==false||!Array.isArray(report.receipts)||report.receipts.length>100)throw fail("TREE_REPORT_UNSAFE");
 const items=new Map([["result.json",null]]);
 if(summary.state==="TREE_NATIVE_CAPTURE_SUITE_OBSERVED"){
  const build=JSON.parse(await fs.readFile(path.join(stage,"build.json"),"utf8"));
  if(typeof build.release_sha256!=="string"||!/^[a-f0-9]{64}$/.test(build.release_sha256))throw fail("TREE_BUILD_HASH_MISSING");
  // Preserve exact executable bytes for later host-specific signed rebind.
  // Never compile again during an installation from qualified evidence.
  items.set("candidate-tree-broker",build.release_sha256);
 }
 for(const rel of ["native-evidence.json","build.json"])if(await fs.stat(path.join(stage,rel)).then(()=>true,()=>false))items.set(rel,null);
 for(const receipt of report.receipts){
  if(!receipt||typeof receipt!=="object"||!receipt.files||typeof receipt.files!=="object")throw fail("TREE_RECEIPT_UNSAFE");
  for(const key of ["request","response","stderr"]){
   const rel=receipt.files[key],expected=receipt[key+"_sha256"];
   if(!validRel(rel)||!/^receipts\/[0-9]{4}-(request|response|stderr)\.bin$/.test(rel)||!/^[a-f0-9]{64}$/.test(expected))throw fail("TREE_RECEIPT_UNSAFE");
   if(items.has(rel))throw fail("TREE_RECEIPT_DUPLICATE");
   items.set(rel,expected);
  }
 }
 if(items.size>304)throw fail("TREE_PACKAGE_COUNT_LIMIT");
 await fs.mkdir(destination,{recursive:false,mode:0o700});
 let total=0;const inventory=[];
 for(const [rel,expected] of items){
  if(!validRel(rel))throw fail("TREE_PACKAGE_PATH_UNSAFE");
  const source=path.join(stage,rel),info=await fs.lstat(source);
  if(!info.isFile()||info.isSymbolicLink()||info.nlink!==1||info.uid!==process.getuid()||
     (info.mode&0o077)!==0||info.size>32*1024*1024)throw fail("TREE_PACKAGE_FILE_UNSAFE");
  total+=info.size;if(total>350*1024*1024)throw fail("TREE_PACKAGE_BYTES_LIMIT");
  const bytes=await fs.readFile(source);
  if(bytes.length!==info.size||(expected&&sha(bytes)!==expected))throw fail("TREE_PACKAGE_HASH_MISMATCH");
  const target=path.join(destination,rel);await fs.mkdir(path.dirname(target),{recursive:true,mode:0o700});
  await fs.writeFile(target,bytes,{flag:"wx",mode:0o600});
  inventory.push({path:rel,bytes:bytes.length,sha256:sha(bytes)});
 }
 await fs.writeFile(path.join(destination,"artifact-inventory.json"),
  JSON.stringify({format:"gsa-native-tree-artifact-v1",state:summary.state,stage_basename:path.basename(stage),files:inventory},null,2),{flag:"wx",mode:0o600});
 return {state:summary.state,count:inventory.length,bytes:total};
}
if(process.argv[1]&&path.resolve(process.argv[1])===fileURLToPath(import.meta.url)){
 const [, ,summary,output]=process.argv;
 if(process.platform!=="darwin"||!summary||!output||!path.isAbsolute(output)||output.startsWith("/private/tmp/gsa-directory-native-"))process.exitCode=1;
 else packageNativeTreeEvidence(summary,output).then(result=>console.log(JSON.stringify(result))).catch(error=>{console.error(error.code??"TREE_PACK_FAILED");process.exitCode=1;});
}
